<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('petugas');require_once __DIR__.'/../../includes/document_tools.php';$pid=(int)($_GET['petugas_id']??0);require_selected_petugas($pid);$q=$pdo->prepare("SELECT p.id_petugas,p.id_user,p.id_kegiatan,k.tujuan_akhir FROM petugas p JOIN kegiatan k ON k.id_kegiatan=p.id_kegiatan WHERE p.id_petugas=? AND p.id_user=? AND p.deleted_at IS NULL");$q->execute([$pid,current_user()['id_user']]);$p=$q->fetch();if(!$p||!in_array($p['tujuan_akhir'],['lpd','keduanya'],true)){http_response_code(403);exit('Akses ditolak atau LPD tidak tersedia.');}if(!class_exists('ZipArchive')){http_response_code(500);exit('Aktifkan ekstensi ZipArchive pada php.ini XAMPP.');}$s=$pdo->prepare("SELECT ph.id_progress,ph.tanggal,COUNT(dp.id_detail) jumlah_detail,SUM(CASE WHEN dp.id_detail IS NOT NULL AND (dp.uraian_kegiatan IS NULL OR TRIM(dp.uraian_kegiatan)='' OR dp.output_tujuan IS NULL OR TRIM(dp.output_tujuan)='') THEN 1 ELSE 0 END) incomplete FROM progress_harian ph LEFT JOIN detail_progress dp ON dp.id_progress=ph.id_progress WHERE ph.id_petugas=? GROUP BY ph.id_progress,ph.tanggal ORDER BY ph.tanggal");$s->execute([$pid]);$tmp=tempnam(sys_get_temp_dir(),'lpd');$zip=new ZipArchive();$zip->open($tmp,ZipArchive::CREATE|ZipArchive::OVERWRITE);$count=0;foreach($s->fetchAll() as $r){if(!(int)$r['jumlah_detail']||(int)$r['incomplete']>0)continue;$pdf=sipacak_progress_pdf($pdo,(int)$r['id_progress']);$zip->addFromString('LPD_'.$r['tanggal'].'.pdf',$pdf);$count++;}$zip->close();if(!$count){unlink($tmp);http_response_code(404);exit('Belum ada LPD yang dapat diunduh.');}$name='LPD_Petugas_'.$pid.'.zip';header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="'.$name.'"');header('Content-Length: '.filesize($tmp));readfile($tmp);unlink($tmp);exit;
